    fun text(language: String, key: String): String? = when (key) {
        "readRetained" -> retained[language]
        "draftRetired" -> recovery[language]?.getOrNull(0)
        "retainedDraft" -> recovery[language]?.getOrNull(1)
        "copyOwnedDraft" -> recovery[language]?.getOrNull(2)
        else -> keys.indexOf(key).takeIf { it >= 0 }?.let { rows[language]?.getOrNull(it) }
    }
    fun complete() = Strings.languages.keys.all { rows[it]?.size == keys.size && retained[it] != null && recovery[it]?.size == 3 }
}
